async (page) => {
  const { execSync } = require('child_process');
  const fs = require('fs');
  // Make script executable
  execSync('chmod +x /tmp/mcp-workspace/workspace/monitor_cpu.sh');
  // Run the script (this will take ~1 minute)
  const out = execSync('bash /tmp/mcp-workspace/workspace/monitor_cpu.sh', { timeout: 120000 }).toString();
  // Read back the log
  const log = fs.readFileSync('/tmp/mcp-workspace/workspace/cpu_monitor.log', 'utf8');
  return { stdout: out, log };
}

